files.content:
:root {
  --bg: #1a1c2c;
  --card: #2b2f4a;
  --ink: #f4f4f4;
  --accent: #ffcd75;
  --accent-ink: #1a1c2c;
  --muted: #9aa0c0;
  --border: #0e0f1a;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: var(--bg);
  background-image:
    linear-gradient(transparent 95%, rgba(255, 205, 117, 0.06) 95%),
    linear-gradient(90deg, transparent 95%, rgba(255, 205, 117, 0.06) 95%);
  background-size: 24px 24px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 16px;
  color: var(--ink);
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  padding: 28px 24px 32px;
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--border);
}

.title {
  margin: 0 0 24px;
  font-size: 1.75rem;
  text-align: center;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.field {
  margin: 0 0 20px;
  border: 0;
  padding: 0;
}

.field label,
.field legend {
  display: block;
  margin-bottom: 8px;
  font-size: 1rem;
  color: var(--muted);
  padding: 0;
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  font: inherit;
  font-size: 1.125rem;
  color: var(--ink);
  background: var(--bg);
  border: 3px solid var(--border);
  border-radius: 0;
  outline: none;
}

input[type="number"]:focus-visible {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent);
}

.tip-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.tip-btn {
  padding: 12px 8px;
  font: inherit;
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--ink);
  background: var(--bg);
  border: 3px solid var(--border);
  cursor: pointer;
  transition: transform 0.05s ease, background 0.1s ease, color 0.1s ease;
}

.tip-btn:hover {
  background: #3a3f60;
}

.tip-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translate(2px, 2px);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--accent-ink);
  border-color: var(--border);
}

.results {
  margin-top: 28px;
  padding-top: 20px;
  border-top: 3px dashed var(--border);
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding: 8px 0;
}

.result-label {
  color: var(--muted);
  font-size: 1rem;
}

.result-value {
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--ink);
}

.total-row .result-value {
  color: var(--accent);
  font-size: 1.5rem;
}

@media (max-width: 360px) {
  .card {
    padding: 20px 16px 24px;
    box-shadow: 6px 6px 0 var(--border);
  }

  .title {
    font-size: 1.5rem;
  }

  .tip-buttons {
    gap: 6px;
  }

  .tip-btn {
    padding: 10px 4px;
    font-size: 1rem;
  }
}

(function () {
  'use strict';

  var billInput = document.getElementById('bill');
  var peopleInput = document.getElementById('people');
  var tipButtons = Array.prototype.slice.call(document.querySelectorAll('.tip-btn'));
  var tipPerPersonEl = document.getElementById('tipPerPerson');
  var totalPerPersonEl = document.getElementById('totalPerPerson');

  var selectedTip = 15;

  function formatCurrency(value) {
    if (!isFinite(value)) return '$0.00';
    return '$' + value.toFixed(2);
  }

  function parseBill() {
    var value = parseFloat(billInput.value);
    if (!isFinite(value) || value < 0) return 0;
    return value;
  }

  function parsePeople() {
    var value = parseInt(peopleInput.value, 10);
    if (!isFinite(value) || value < 1) return 1;
    return value;
  }

  function setActiveTip(percent) {
    selectedTip = percent;
    tipButtons.forEach(function (btn) {
      var isActive = parseInt(btn.getAttribute('data-tip'), 10) === percent;
      btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    });
  }

  function calculate() {
    var bill = parseBill();
    var people = parsePeople();
    var tipTotal = bill * (selectedTip / 100);
    var grandTotal = bill + tipTotal;
    var tipPerPerson = tipTotal / people;
    var totalPerPerson = grandTotal / people;

    tipPerPersonEl.textContent = formatCurrency(tipPerPerson);
    totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var percent = parseInt(btn.getAttribute('data-tip'), 10);
      setActiveTip(percent);
      calculate();
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  setActiveTip(selectedTip);
  calculate();
})();
